contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, bool freeze, address caller) public payable {
        require(caller == address(this) || caller != c.owner());

        bool reverted;
        if (caller == address(this)) {
            try c.freezeAccount(target, freeze) { reverted = false; } catch { reverted = true; }
        } else {
            (bool ok, ) = address(c).call(abi.encodeWithSignature("freezeAccount(address,bool)", target, freeze));
            reverted = !ok;
        }

        if (caller == c.owner()) {
            assert(!reverted && c.frozenAccount(target) == freeze);
        } else {
            assert(reverted || c.frozenAccount(target) == freeze);
        }
    }

    receive() external payable {}
}

