contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, bool freeze) public payable {
        require(target != address(0));

        // unfreeze first to clear any prior freeze state, ensuring 'freeze=true' path is not blocked by a prior freeze
        c.freezeAccount(target, false);

        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!freeze) {
            assert(!reverted && c.frozenAccount(target) == false);
        } else {
            assert(!reverted && c.frozenAccount(target) == true);
        }
    }

    receive() external payable {}
}

